from fractions import Fraction

def bound(rule, K, a, b, n):
    if rule == "trapezoid":
        return K * (b - a)**3 / (12 * n**2)
    if rule == "midpoint":
        return K * (b - a)**3 / (24 * n**2)
    return K * (b - a)**5 / (180 * n**4)

def smallest_n(label, rule, K, a, b, tol):
    print(f"{label}: {rule}, K = {K}, [{a}, {b}], tolerance {float(tol)}")
    if rule == "simpson":
        step = 2
    else:
        step = 1
    n = step
    while bound(rule, K, a, b, n) > tol:
        n = n + step
    if n > step:
        print(f"  n = {n - step}: bound {float(bound(rule, K, a, b, n - step)):.8f}, too big")
    print(f"  n = {n}: bound {float(bound(rule, K, a, b, n)):.8f} <= {float(tol)}")

print(f"Example 2: the trapezoid bound for n = 4 is {bound('trapezoid', Fraction(2), 0, 2, 4)}")
smallest_n("Example 5", "trapezoid", Fraction(2), 1, 2, Fraction(1, 10000))
smallest_n("Example 6", "simpson", Fraction(24), 1, 2, Fraction(1, 10000))
smallest_n("Example 8, the midpoint rule", "midpoint", Fraction(2), 1, 2, Fraction(1, 10000))
smallest_n("Example 11", "simpson", Fraction(12), 0, 1, Fraction(5, 10000000))

