import math

def trapezoid(f, a, b, n):
    dx = (b - a) / n
    return dx / 2 * (f(a) + 2 * sum(f(a + i * dx) for i in range(1, n)) + f(b))

def midpoint(f, a, b, n):
    dx = (b - a) / n
    return dx * sum(f(a + (i - 0.5) * dx) for i in range(1, n + 1))

def simpson(f, a, b, n):
    h = (b - a) / n
    total = f(a) + f(b)
    for i in range(1, n):
        if i % 2 == 1:
            total = total + 4 * f(a + i * h)
        else:
            total = total + 2 * f(a + i * h)
    return total * h / 3

def table(label, f, a, b, exact):
    print(label)
    old_t = old_s = 0
    for n in [2, 4, 8, 16]:
        et = exact - trapezoid(f, a, b, n)
        es = exact - simpson(f, a, b, n)
        line = f"  n = {n:2}: T error {et:.3e}, S error {es:.3e}"
        if old_t != 0:
            line = line + f", ratios {old_t / et:.2f} and {old_s / es:.2f}"
        print(line)
        old_t, old_s = et, es

table("Examples 1 and 2, 1/x on [1, 2]", lambda x: 1 / x, 1, 2, math.log(2))
table("Example 7, sqrt(x) on [0, 1]", math.sqrt, 0, 1, 2 / 3)
T4, M4 = trapezoid(lambda x: 1 / x, 1, 2, 4), midpoint(lambda x: 1 / x, 1, 2, 4)
print(f"Example 4: (T_4 + 2 M_4)/3 = {(T4 + 2 * M4) / 3:.6f}, S_8 = {simpson(lambda x: 1 / x, 1, 2, 8):.6f}")

