from fractions import Fraction

def trapezoid(f, a, b, n):
    dx = (b - a) / n
    return dx / 2 * (f(a) + 2 * sum(f(a + i * dx) for i in range(1, n)) + f(b))

def simpson(f, a, b, n):
    h = (b - a) / n
    total = f(a) + f(b)
    for i in range(1, n):
        if i % 2 == 1:
            total = total + 4 * f(a + i * h)
        else:
            total = total + 2 * f(a + i * h)
    return total * h / 3

def part(err, old):
    if err == 0:
        return "0"
    text = f"{float(err):.3e}"
    if old != 0:
        text = text + f" (ratio {float(old / err):.2f})"
    return text

n_problems = int(input())
for p in range(1, n_problems + 1):
    # input().split() cuts a line at its spaces into a list of words
    cs = [Fraction(c) for c in input().split()]
    a, b = [Fraction(v) for v in input().split()]
    f = lambda x: sum(cs[k] * x**k for k in range(len(cs)))
    exact = sum(cs[k] * (b**(k + 1) - a**(k + 1)) / (k + 1) for k in range(len(cs)))
    print(f"problem {p}: f: {' '.join(str(c) for c in cs)} on [{a}, {b}], exact {exact}")
    old_t = old_s = 0
    for n in [2, 4, 8, 16]:
        et = exact - trapezoid(f, a, b, n)
        es = exact - simpson(f, a, b, n)
        print(f"  n = {n}: T error {part(et, old_t)}, S error {part(es, old_s)}")
        old_t, old_s = et, es
